INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-PA-2026-0904-AURUM-TAPAJOS','ILLEGAL_MINING',ARRAY['ILLEGAL_MINING','PROTECTED_AREA_INVASION']::text[],'CONFIRMED','HIGH','Aurum Tapajós','2026-09-04T11:52:00-03:00','2026-09-04T11:52:00-03:00','2026-09-16T02:05:00+07:00','2026-09-16T02:05:00+07:00',TRUE,'APA do Tapajós / Novo Progresso','Pará','Brasil',-7.143,-55.378,'municipality_centroid_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-deflagra-operacao-contra-exploracao-ilegal-de-ouro-em-area-de-protecao-ambiental-no-para','006a6366b2b569fba6735173721394ff2a27234070f17b8ed570655638932d28','{"id": "BR-PA-2026-0904-AURUM-TAPAJOS", "title": {"pt": "Operação Aurum Tapajós apura exploração ilegal de ouro na APA do Tapajós", "en": "Operation Aurum Tapajós investigates illegal gold mining in the Tapajós protected area", "es": "Operación Aurum Tapajós investiga extracción ilegal de oro en el APA del Tapajós"}, "summary": {"pt": "A PF cumpriu dois mandados de busca e apreensão em investigação sobre exploração ilegal de ouro na APA do Tapajós. A apuração teve origem em fiscalização do ICMBio que identificou atividade mineral sem licença válida em cerca de 40 hectares de floresta nativa.", "en": "Federal Police served two search warrants in an investigation into illegal gold mining in the Tapajós Environmental Protection Area. The case originated from ICMBio inspection that identified unlicensed mining over about 40 hectares of native forest.", "es": "La Policía Federal cumplió dos órdenes de registro en una investigación sobre extracción ilegal de oro en el APA del Tapajós. La investigación surgió de una fiscalización del ICMBio que identificó minería sin licencia en unas 40 hectáreas de bosque nativo."}, "case_context": {"pt": "Trata-se de investigação oficial em unidade de conservação; o ponto cartográfico representa Novo Progresso de forma aproximada, não o sítio exato investigado.", "en": "This is an official investigation in a protected area; the mapped point approximates Novo Progresso, not the exact investigated site.", "es": "Se trata de una investigación oficial en un área protegida; el punto cartográfico aproxima Novo Progresso, no el sitio exacto investigado."}, "primary_crime_type": "ILLEGAL_MINING", "crime_types": ["ILLEGAL_MINING", "PROTECTED_AREA_INVASION"], "operation_name": "Aurum Tapajós", "agencies": ["Polícia Federal", "ICMBio"], "occurred_at": "2026-09-04T11:52:00-03:00", "published_at": "2026-09-04T11:52:00-03:00", "added_at": "2026-09-16T02:05:00+07:00", "updated_at": "2026-09-16T02:05:00+07:00", "backfill": true, "validation_status": "CONFIRMED", "priority": "HIGH", "location": {"name": "APA do Tapajós / Novo Progresso", "admin1": "Pará", "country": "Brasil", "lat": -7.143, "lon": -55.378, "precision": "municipality_centroid_approximate"}, "protected_area": {"is_protected_area": true, "name": "Área de Proteção Ambiental do Tapajós"}, "impacts": {"indigenous_or_local_communities": false}, "cross_border": false, "keywords": ["ouro", "APA do Tapajós", "Novo Progresso", "40 hectares"], "sources": [{"publisher": "Polícia Federal", "url": "https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-deflagra-operacao-contra-exploracao-ilegal-de-ouro-em-area-de-protecao-ambiental-no-para", "published_at": "2026-09-04T11:52:00-03:00", "source_type": "official"}], "source_media": [], "legal_status_note": "Official enforcement or investigation record; no inference of guilt beyond the cited source."}'::jsonb) ON CONFLICT (id) DO NOTHING;
