vio de 50 trabajadores."}, "case_context": {"pt": "O registro representa uma investigação oficial; não implica condenação dos investigados.", "en": "The record represents an official investigation and does not imply conviction of those investigated.", "es": "El registro representa una investigación oficial y no implica condena de los investigados."}, "primary_crime_type": "ILLEGAL_DEFORESTATION", "crime_types": ["ILLEGAL_DEFORESTATION", "LAND_GRABBING"], "operation_name": "Correntes do Capital", "agencies": ["Polícia Federal"], "occurred_at": "2026-08-27T08:54:00-04:00", "published_at": "2026-08-27T08:54:00-04:00", "added_at": "2026-09-16T02:05:00+07:00", "updated_at": "2026-09-16T02:05:00+07:00", "backfill": true, "validation_status": "CONFIRMED", "priority": "URGENT", "location": {"name": "Manicoré", "admin1": "Amazonas", "country": "Brasil", "lat": -5.809, "lon": -61.3, "precision": "municipality_centroid_approximate"}, "protected_area": {"is_protected_area": false}, "impacts": {"indigenous_or_local_communities": false}, "cross_border": false, "keywords": ["desmatamento", "terras públicas", "trabalho análogo à escravidão", "Manicoré"], "sources": [{"publisher": "Polícia Federal", "url": "https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-reprime-crimes-ambientais-e-exploracao-de-trabalhadores-em-manicore-am", "published_at": "2026-08-27T08:54:00-04:00", "source_type": "official"}], "source_media": [], "legal_status_note": "Official enforcement or investigation record; no inference of guilt beyond the cited source."}'::jsonb) ON CONFLICT (id) DO NOTHING;
