"primary_crime_type": "ILLEGAL_MINING", "crime_types": ["ILLEGAL_MINING"], "operation_name": "Ação PF-Ibama Rio Madeira", "agencies": ["Polícia Federal", "Ibama"], "occurred_at": "2026-08-26T12:00:00-04:00", "published_at": "2026-08-27T12:04:00-04:00", "added_at": "2026-09-16T02:05:00+07:00", "updated_at": "2026-09-16T02:05:00+07:00", "backfill": true, "validation_status": "CONFIRMED", "priority": "HIGH", "location": {"name": "Rio Madeira / Porto Velho", "admin1": "Rondônia", "country": "Brasil", "lat": -8.761, "lon": -63.903, "precision": "river_segment_approximate"}, "protected_area": {"is_protected_area": false}, "impacts": {"indigenous_or_local_communities": false}, "cross_border": false, "keywords": ["dragas", "ouro", "Rio Madeira", "Ibama"], "sources": [{"publisher": "Polícia Federal", "url": "https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-e-ibama-inutilizam-dez-dragas-em-acao-contra-garimpo-ilegal-no-rio-madeira", "published_at": "2026-08-27T12:04:00-04:00", "source_type": "official"}], "source_media": [], "legal_status_note": "Official enforcement or investigation record; no inference of guilt beyond the cited source."}'::jsonb) ON CONFLICT (id) DO NOTHING;
