INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-MT-2026-0818-SOLO-SAGRADO','ILLEGAL_MINING',ARRAY['ILLEGAL_MINING','PROTECTED_AREA_INVASION']::text[],'CONFIRMED','URGENT','Solo Sagrado','2026-08-18T09:25:00-04:00','2026-08-18T09:25:00-04:00','2026-09-16T02:05:00+07:00','2026-09-16T02:05:00+07:00',TRUE,'Terra Indígena Sararé','Mato Grosso','Brasil',-14.72,-59.5,'indigenous_land_centroid_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-receita-e-mpf-combatem-extracao-ilegal-de-ouro-em-terra-indigena-de-mato-grosso','d58525cc73f6a74ea5733f3a69699640ec5f6dffc80078445d960ef8b4a00858','{"id": "BR-MT-2026-0818-SOLO-SAGRADO", "title": {"pt": "Operação Solo Sagrado combate extração e comercialização ilegal de ouro na TI Sararé", "en": "Operation Solo Sagrado targets illegal gold extraction and trade in Sararé Indigenous Land", "es": "Operación Solo Sagrado combate extracción y comercialización ilegal de oro en la TI Sararé"}, "summary": {"pt": "PF, Receita Federal e MPF realizaram operação contra estrutura investigada por extração ilegal de ouro na Terra Indígena Sararé e inserção do minério no mercado formal. Foram cumpridos 10 mandados de busca e apreensão e um de prisão preventiva.", "en": "Federal Police, Federal Revenue and federal prosecutors carried out an operation against a structure investigated for illegal gold extraction in Sararé Indigenous Land and laundering the mineral into the formal market. Ten search warrants and one preventive-arrest warrant were executed.", "es": "Policía Federal, Receita Federal y MPF realizaron una operación contra una estructura investigada por extracción ilegal de oro en la Tierra Indígena Sararé e inserción del mineral en el mercado formal. Se cumplieron diez órdenes de registro y una de prisión preventiva."}, "case_context": {"pt": "A coordenada é o centro aproximado da TI Sararé, calculado a partir da faixa geográfica publicada para o território; não indica frente de garimpo específica.", "en": "The coordinate is an approximate center of Sararé Indigenous Land based on its published geographic range; it does not indicate a specific mining front.", "es": "La coordenada es un centro aproximado de la Tierra Indígena Sararé basado en su rango geográfico publicado; no indica un frente minero específico."}, "primary_crime_type": "ILLEGAL_MINING", "crime_types": ["ILLEGAL_MINING", "PROTECTED_AREA_INVASION"], "operation_name": "Solo Sagrado", "agencies": ["Polícia Federal", "Receita Federal", "Ministério Público Federal"], "occurred_at": "2026-08-18T09:25:00-04:00", "published_at": "2026-08-18T09:25:00-04:00", "added_at": "2026-09-16T02:05:00+07:00", "updated_at": "2026-09-16T02:05:00+07:00", "backfill": true, "validation_status": "CONFIRMED", "priority": "URGENT", "location": {"name": "Terra Indígena Sararé", "admin1": "Mato Grosso", "country": "Brasil", "lat": -14.72, "lon": -59.5, "precision": "indigenous_land_centroid_approximate"}, "protected_area": {"is_protected_area": true, "name": "Terra Indígena Sararé"}, "impacts": {"indigenous_or_local_communities": true}, "cross_border": false, "keywords": ["ouro", "Sararé", "Nambikwara", "logística"], "sources": [{"publisher": "Polícia Federal", "url": "https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-receita-e-mpf-combatem-extracao-ilegal-de-ouro-em-terra-indigena-de-mato-grosso", "published_at": "2026-08-18T09:25:00-04:00", "source_type": "official"}, {"publisher": "Receita Federal", "url": "https://www.gov.br/receitafederal/pt-br/assuntos/noticias/2026/agosto/receita-federal-participa-da-operacao-solo-sagrado", "published_at": "2026-08-18T08:13:00-04:00", "source_type": "official"}], "source_media": [], "legal_status_note": "Official enforcement or investigation record; no inference of guilt beyond the cited source."}'::jsonb) ON CONFLICT (id) DO NOTHING;
